2	package com.hedera.node.app.history.impl;
3	
4	import static com.hedera.hapi.node.state.history.WrapsPhase.R1;
5	import static com.hedera.hapi.util.HapiUtils.asTimestamp;
6	import static com.hedera.node.app.history.impl.ProofControllers.isWrapsExtensible;
7	import static com.hedera.node.app.history.schemas.V071HistorySchema.ACTIVE_PROOF_CONSTRUCTION_STATE_ID;
8	import static com.hedera.node.app.history.schemas.V071HistorySchema.LEDGER_ID_STATE_ID;
9	import static com.hedera.node.app.history.schemas.V071HistorySchema.NEXT_PROOF_CONSTRUCTION_STATE_ID;
10	import static com.hedera.node.app.history.schemas.V071HistorySchema.PROOF_KEY_SETS_STATE_ID;
11	import static com.hedera.node.app.history.schemas.V071HistorySchema.PROOF_VOTES_STATE_ID;
12	import static com.hedera.node.app.history.schemas.V071HistorySchema.WRAPS_MESSAGE_HISTORIES_STATE_ID;
13	import static com.hedera.node.app.history.schemas.V0730HistorySchema.WRAPS_PROVING_KEY_HASH_STATE_ID;
14	import static com.hedera.node.app.service.roster.impl.ActiveRosters.Phase.BOOTSTRAP;
