16	import static java.util.Objects.requireNonNull;
17	import static org.hiero.consensus.roster.RosterUtils.isWeightRotation;
18	
19	import com.hedera.hapi.node.state.history.ConstructionNodeId;
20	import com.hedera.hapi.node.state.history.HistoryProof;
21	import com.hedera.hapi.node.state.history.HistoryProofConstruction;
22	import com.hedera.hapi.node.state.history.HistoryProofVote;
23	import com.hedera.hapi.node.state.history.ProofKeySet;
24	import com.hedera.hapi.node.state.history.WrapsMessageHistory;
25	import com.hedera.hapi.node.state.history.WrapsSigningState;
26	import com.hedera.hapi.node.state.primitives.ProtoBytes;
27	import com.hedera.hapi.node.state.roster.Roster;
28	import com.hedera.hapi.node.state.roster.RosterEntry;
29	import com.hedera.hapi.platform.state.NodeId;
30	import com.hedera.node.app.history.WritableHistoryStore;
31	import com.hedera.node.app.service.roster.impl.ActiveRosters;
32	import com.hedera.node.config.data.TssConfig;
33	import com.hedera.pbj.runtime.io.buffer.Bytes;
34	import com.swirlds.state.spi.WritableKVState;
35	import com.swirlds.state.spi.WritableSingletonState;
36	import com.swirlds.state.spi.WritableStates;
37	import edu.umd.cs.findbugs.annotations.NonNull;
38	import edu.umd.cs.findbugs.annotations.Nullable;
39	import java.time.Duration;
40	import java.time.Instant;
41	import java.util.List;
42	import java.util.SortedSet;
43	import java.util.function.BiFunction;
44	import java.util.function.Consumer;
45	import java.util.function.Function;
46	import java.util.stream.Collectors;
47	import java.util.stream.Stream;
48	import org.apache.logging.log4j.LogManager;
49	import org.apache.logging.log4j.Logger;
50	
51	/**
52	 * Default implementation of {@link WritableHistoryStore}.
53	 */
54	public class WritableHistoryStoreImpl extends ReadableHistoryStoreImpl implements WritableHistoryStore {
55	
56	    private static final Logger log = LogManager.getLogger(WritableHistoryStoreImpl.class);
57	
58	    private final WritableSingletonState<ProtoBytes> ledgerId;
59	    private final WritableSingletonState<ProtoBytes> wrapsProvingKeyHash;
60	    private final WritableSingletonState<HistoryProofConstruction> nextConstruction;
61	    private final WritableSingletonState<HistoryProofConstruction> activeConstruction;
62	    private final WritableKVState<NodeId, ProofKeySet> proofKeySets;
63	    private final WritableKVState<ConstructionNodeId, HistoryProofVote> votes;
64	    private final WritableKVState<ConstructionNodeId, WrapsMessageHistory> wrapsMessageHistories;
65	
66	    public WritableHistoryStoreImpl(@NonNull final WritableStates states) {
67	        super(states);
68	        this.ledgerId = states.getSingleton(LEDGER_ID_STATE_ID);
69	        this.wrapsProvingKeyHash = states.getSingleton(WRAPS_PROVING_KEY_HASH_STATE_ID);
70	        this.nextConstruction = states.getSingleton(NEXT_PROOF_CONSTRUCTION_STATE_ID);
71	        this.activeConstruction = states.getSingleton(ACTIVE_PROOF_CONSTRUCTION_STATE_ID);
72	        this.proofKeySets = states.get(PROOF_KEY_SETS_STATE_ID);
73	        this.votes = states.get(PROOF_VOTES_STATE_ID);
74	        this.wrapsMessageHistories = states.get(WRAPS_MESSAGE_HISTORIES_STATE_ID);
75	    }
76	
77	    @Override
78	    public @NonNull HistoryProofConstruction getOrCreateConstruction(
79	            @NonNull final ActiveRosters activeRosters,
80	            @NonNull final Instant now,
81	            @NonNull final TssConfig tssConfig) {
82	        requireNonNull(activeRosters);
83	        requireNonNull(now);
84	        requireNonNull(tssConfig);
85	        final var phase = activeRosters.phase();
86	        if (phase == HANDOFF) {
87	            throw new IllegalArgumentException("Handoff phase has no construction");
88	        }
89	        var construction = getConstructionFor(activeRosters);
90	        if (construction == null) {
91	            final var gracePeriod = phase == BOOTSTRAP
92	                    ? tssConfig.bootstrapProofKeyGracePeriod()
93	                    : tssConfig.transitionProofKeyGracePeriod();
94	            construction = updateForNewConstruction(
95	                    activeRosters.sourceRosterHash(),
96	                    activeRosters.targetRosterHash(),
97	                    activeRosters::findRelatedRoster,
98	                    now,
99	                    gracePeriod);
100	        }
101	        return construction;
102	    }
103	
104	    @Override
105	    public boolean setProofKey(final long nodeId, @NonNull final Bytes proofKey, @NonNull final Instant now) {
106	        requireNonNull(proofKey);
107	        requireNonNull(now);
108	        final var id = new NodeId(nodeId);
109	        var keySet = proofKeySets.get(id);
110	        boolean inUse = false;
111	        if (keySet == null) {
112	            inUse = true;
113	            keySet = ProofKeySet.newBuilder()
114	                    .key(proofKey)
115	                    .adoptionTime(asTimestamp(now))
116	                    .build();
117	        } else {
118	            keySet = keySet.copyBuilder().nextKey(proofKey).build();
119	        }
120	        proofKeySets.put(id, keySet);
121	        return inUse;
122	    }
123	
124	    @Override
125	    public HistoryProofConstruction setAssemblyTime(final long constructionId, @NonNull final Instant now) {
126	        requireNonNull(now);
127	        return updateOrThrow(constructionId, (c, b) -> b.assemblyStartTime(asTimestamp(now)));
128	    }
129	
130	    @Override
131	    public void addProofVote(final long nodeId, final long constructionId, @NonNull final HistoryProofVote vote) {
132	        requireNonNull(vote);
133	        votes.put(new ConstructionNodeId(constructionId, nodeId), vote);
134	    }
135	
136	    @Override
137	    public void clearProofVotes(final long constructionId, @NonNull final SortedSet<Long> nodeIds) {
138	        requireNonNull(nodeIds);
139	        nodeIds.forEach(nodeId -> votes.remove(new ConstructionNodeId(constructionId, nodeId)));
140	    }
141	
142	    @Override
143	    public void addWrapsMessage(final long constructionId, @NonNull final WrapsMessagePublication publication) {
144	        requireNonNull(publication);
145	        final var key = new ConstructionNodeId(constructionId, publication.nodeId());
146	        final var history = wrapsMessageHistories.get(key);
147	        if (history == null) {
148	            wrapsMessageHistories.put(key, new WrapsMessageHistory(List.of(publication.asWrapsMessageDetails())));
149	        } else {
150	            wrapsMessageHistories.put(
151	                    key,
152	                    new WrapsMessageHistory(
153	                            Stream.concat(history.messages().stream(), Stream.of(publication.asWrapsMessageDetails()))
154	                                    .toList()));
155	        }
156	    }
157	
158	    @Override
159	    public void updateWrapsSigningState(
160	            final long constructionId, @NonNull final Consumer<WrapsSigningState.Builder> spec) {
161	        requireNonNull(spec);
162	        updateOrThrow(constructionId, (c, b) -> {
163	            final var sb = c.wrapsSigningStateOrElse(WrapsSigningState.DEFAULT).copyBuilder();
164	            spec.accept(sb);
165	            return b.wrapsSigningState(sb.build());
166	        });
167	    }
168	
169	    @Override
170	    public HistoryProofConstruction completeProof(final long constructionId, @NonNull final HistoryProof proof) {
171	        requireNonNull(proof);
172	        return updateOrThrow(constructionId, (c, b) -> b.targetProof(proof));
173	    }
174	
175	    @Override
176	    public HistoryProofConstruction failForReason(final long constructionId, @NonNull final String reason) {
177	        requireNonNull(reason);
178	        return updateOrThrow(constructionId, (c, b) -> b.failureReason(reason));
179	    }
180	
181	    @Override
182	    public HistoryProofConstruction restartWrapsSigning(
183	            final long constructionId, @NonNull final SortedSet<Long> sourceNodeIds) {
184	        requireNonNull(sourceNodeIds);
185	        sourceNodeIds.forEach(nodeId -> wrapsMessageHistories.remove(new ConstructionNodeId(constructionId, nodeId)));
186	        return updateOrThrow(constructionId, (c, b) -> b.wrapsSigningState(
187	                        WrapsSigningState.newBuilder().phase(R1).build())
188	                .wrapsRetryCount(c.wrapsRetryCount() + 1));
189	    }
190	
191	    @Override
192	    public void setLedgerId(@NonNull final Bytes bytes) {
193	        requireNonNull(bytes);
194	        ledgerId.put(new ProtoBytes(bytes));
195	    }
196	
197	    @Override
198	    public void setWrapsProvingKeyHash(@NonNull final Bytes hash) {
199	        requireNonNull(hash);
200	        wrapsProvingKeyHash.put(new ProtoBytes(hash));
201	    }
202	
203	    @Override
204	    public boolean handoff(
205	            @NonNull final Roster fromRoster, @Nullable final Roster toRoster, @Nullable final Bytes toRosterHash) {
206	        return handoff(fromRoster, toRoster, toRosterHash, false);
207	    }
208	
209	    @Override
210	    public boolean handoff(
211	            @NonNull final Roster fromRoster,
212	            @Nullable final Roster toRoster,
213	            @Nullable final Bytes toRosterHash,
214	            final boolean forceHandoff) {
215	        requireNonNull(fromRoster);
216	        final var upcomingConstruction = requireNonNull(nextConstruction.get());
217	        final boolean handoffMatches =
218	                toRosterHash == null || upcomingConstruction.targetRosterHash().equals(toRosterHash);
219	        if (!handoffMatches) {
220	            if (!forceHandoff) {
221	                return false;
222	            }
223	            if (!upcomingConstruction.hasTargetProof()) {
224	                log.warn(
225	                        "Ignoring forced handoff to incomplete history construction #{}",
226	                        upcomingConstruction.constructionId());
227	                return false;
228	            }
229	            log.warn(
230	                    "Forcing handoff to history construction #{} with different target roster",
231	                    upcomingConstruction.constructionId());
232	        }
233	        // The next construction is becoming the active one; so purge obsolete votes now
234	        final var obsoleteConstruction = requireNonNull(activeConstruction.get());
235	        purgePublications(obsoleteConstruction.constructionId(), fromRoster);
236	        if (toRoster != null && fromRoster != toRoster && !isWeightRotation(fromRoster, toRoster)) {
237	            final var survivingNodeIds =
238	                    toRoster.rosterEntries().stream().map(RosterEntry::nodeId).collect(Collectors.toSet());
239	            fromRoster.rosterEntries().forEach(entry -> {
240	                final long nodeId = entry.nodeId();
241	                if (!survivingNodeIds.contains(nodeId)) {
242	                    proofKeySets.remove(new NodeId(nodeId));
243	                }
244	            });
245	        }
246	        log.info("Handing off to upcoming construction #{}", upcomingConstruction.constructionId());
247	        // And finally, make the next construction the active one
248	        activeConstruction.put(upcomingConstruction);
249	        nextConstruction.put(HistoryProofConstruction.DEFAULT);
250	        return true;
251	    }
252	
253	    /**
254	     * Updates the construction with the given ID using the given spec.
255	     * @param constructionId the construction ID
256	     * @param spec the spec
257	     * @return the updated construction
258	     */
259	    private HistoryProofConstruction updateOrThrow(
260	            final long constructionId,
261	            @NonNull
262	                    final BiFunction<
263	                                    HistoryProofConstruction,
264	                                    HistoryProofConstruction.Builder,
265	                                    HistoryProofConstruction.Builder>
266	                            spec) {
267	        HistoryProofConstruction construction;
268	        if (requireNonNull(construction = activeConstruction.get()).constructionId() == constructionId) {
269	            activeConstruction.put(
270	                    construction =
271	                            spec.apply(construction, construction.copyBuilder()).build());
272	        } else if (requireNonNull(construction = nextConstruction.get()).constructionId() == constructionId) {
273	            nextConstruction.put(
274	                    construction =
275	                            spec.apply(construction, construction.copyBuilder()).build());
276	        } else {
277	            throw new IllegalArgumentException("No construction with id " + constructionId);
278	        }
279	        return construction;
280	    }
281	
282	    /**
283	     * Updates the store for a new construction.
284	     * @param sourceRosterHash the source roster hash
285	     * @param targetRosterHash the target roster hash
286	     * @param lookup the roster lookup
287	     * @param now the current time
288	     * @param gracePeriod the grace period
289	     * @return the new construction
290	     */
291	    private HistoryProofConstruction updateForNewConstruction(
292	            @NonNull final Bytes sourceRosterHash,
293	            @NonNull final Bytes targetRosterHash,
294	            @NonNull final Function<Bytes, Roster> lookup,
295	            @NonNull final Instant now,
296	            @NonNull final Duration gracePeriod) {
297	        var construction = HistoryProofConstruction.newBuilder()
298	                .constructionId(newConstructionId())
299	                .sourceRosterHash(sourceRosterHash)
300	                .targetRosterHash(targetRosterHash)
301	                .gracePeriodEndTime(asTimestamp(now.plus(gracePeriod)))
302	                .build();
303	        if (requireNonNull(activeConstruction.get()).equals(HistoryProofConstruction.DEFAULT)) {
304	            activeConstruction.put(construction);
305	            logNewConstruction(construction, InSlot.ACTIVE, sourceRosterHash, targetRosterHash);
306	        } else {
307	            if (!requireNonNull(nextConstruction.get()).equals(HistoryProofConstruction.DEFAULT)) {
308	                // Before switching to the new construction, purge the existing one's votes and signatures
309	                final var extantConstruction = requireNonNull(nextConstruction.get());
310	                final var sourceRoster = requireNonNull(lookup.apply(extantConstruction.sourceRosterHash()));
311	                purgePublications(extantConstruction.constructionId(), sourceRoster);
312	            }
313	            nextConstruction.put(construction);
314	            logNewConstruction(construction, InSlot.NEXT, sourceRosterHash, targetRosterHash);
315	        }
316	        // Rotate any proof keys requested to be used in the next construction
317	        final var adoptionTime = asTimestamp(now);
318	        final var targetRoster = requireNonNull(lookup.apply(targetRosterHash));
319	        targetRoster.rosterEntries().forEach(entry -> {
320	            final var nodeId = new NodeId(entry.nodeId());
321	            final var keySet = proofKeySets.get(nodeId);
322	            if (keySet != null && keySet.nextKey().length() > 0) {
323	                final var rotatedKeySet = keySet.copyBuilder()
324	                        .key(keySet.nextKey())
325	                        .adoptionTime(adoptionTime)
326	                        .nextKey(Bytes.EMPTY)
327	                        .build();
328	                proofKeySets.put(nodeId, rotatedKeySet);
329	            }
330	        });
331	        return construction;
332	    }
333	
334	    private enum InSlot {
335	        ACTIVE,
336	        NEXT
337	    }
338	
339	    private void logNewConstruction(
340	            @NonNull final HistoryProofConstruction construction,
341	            @NonNull final InSlot slot,
342	            @NonNull final Bytes sourceRosterHash,
343	            @NonNull final Bytes targetRosterHash) {
344	        final var ac = requireNonNull(activeConstruction.get());
345	        log.info(
346	                "Created {} construction #{} for rosters (source={}, target={}) {} source proof",
347	                slot,
348	                construction.constructionId(),
349	                sourceRosterHash,
350	                targetRosterHash,
351	                ac.hasTargetProof()
352	                        ? ("WITH" + (isWrapsExtensible(ac.targetProofOrThrow()) ? " WRAPS-extensible" : ""))
353	                        : "WITHOUT");
354	    }
355	
356	    /**
357	     * Purges the publications for the given construction relative to the given roster.
358	     *
359	     * @param sourceRoster the construction
360	     */
361	    private void purgePublications(final long constructionId, @NonNull final Roster sourceRoster) {
362	        sourceRoster.rosterEntries().forEach(entry -> {
363	            final var key = new ConstructionNodeId(constructionId, entry.nodeId());
364	            votes.remove(key);
365	            wrapsMessageHistories.remove(key);
366	        });
367	    }
368	
369	    /**
370	     * Returns a new construction ID.
371	     */
372	    private long newConstructionId() {
373	        return Math.max(
374	                        requireNonNull(activeConstruction.get()).constructionId(),
375	                        requireNonNull(nextConstruction.get()).constructionId())
376	                + 1;
377	    }
378	}
