1	// SPDX-License-Identifier: Apache-2.0
2	package com.hedera.node.app.history.schemas;
3	
4	import static com.hedera.hapi.util.HapiUtils.SEMANTIC_VERSION_COMPARATOR;
5	import static com.hedera.node.app.history.schemas.V071HistorySchema.ACTIVE_PROOF_CONSTRUCTION_STATE_ID;
6	import static com.hedera.node.app.history.schemas.V071HistorySchema.LEDGER_ID_STATE_ID;
7	import static com.hedera.node.app.history.schemas.V071HistorySchema.NEXT_PROOF_CONSTRUCTION_STATE_ID;
8	import static org.apache.commons.lang3.StringUtils.isBlank;
9	
10	import com.hedera.hapi.node.base.SemanticVersion;
11	import com.hedera.hapi.node.state.history.HistoryProofConstruction;
12	import com.hedera.hapi.node.state.primitives.ProtoBytes;
13	import com.hedera.hapi.platform.state.SingletonType;
14	import com.hedera.node.app.history.HistoryService;
15	import com.hedera.node.config.data.TssConfig;
16	import com.hedera.pbj.runtime.io.buffer.Bytes;
17	import com.swirlds.state.lifecycle.MigrationContext;
18	import com.swirlds.state.lifecycle.Schema;
19	import com.swirlds.state.lifecycle.StateDefinition;
20	import edu.umd.cs.findbugs.annotations.NonNull;
21	import java.util.Objects;
22	import java.util.Set;
23	import org.apache.logging.log4j.LogManager;
24	import org.apache.logging.log4j.Logger;
25	
26	/**
27	 * Registers the expected WRAPS proving key hash singleton state for the {@link HistoryService}.
28	 */
29	public class V0730HistorySchema extends Schema<SemanticVersion> {
30	    private static final Logger log = LogManager.getLogger(V0730HistorySchema.class);
31	
32	    private static final SemanticVersion VERSION =
33	            SemanticVersion.newBuilder().major(0).minor(73).patch(0).build();
34	
35	    public static final String WRAPS_PROVING_KEY_HASH_KEY = "WRAPS_PROVING_KEY_HASH";
36	    public static final int WRAPS_PROVING_KEY_HASH_STATE_ID =
37	            SingletonType.HISTORYSERVICE_I_WRAPS_PROVING_KEY_HASH.protoOrdinal();
38	
39	    private final HistoryService historyService;
40	
41	    public V0730HistorySchema(@NonNull final HistoryService historyService) {
42	        super(VERSION, SEMANTIC_VERSION_COMPARATOR);
43	        this.historyService = Objects.requireNonNull(historyService);
44	    }
45	
46	    @Override
47	    public @NonNull Set<StateDefinition> statesToCreate() {
48	        return Set.of(StateDefinition.singleton(
49	                WRAPS_PROVING_KEY_HASH_STATE_ID, WRAPS_PROVING_KEY_HASH_KEY, ProtoBytes.PROTOBUF));
50	    }
51	
52	    @Override
53	    public void restart(@NonNull final MigrationContext ctx) {
54	        if (!ctx.isGenesis()) {
55	            if (ctx.appConfig().getConfigData(TssConfig.class).historyEnabled()) {
56	                final var writableStates = ctx.newStates();
57	                if (writableStates.<ProtoBytes>getSingleton(LEDGER_ID_STATE_ID).get() == null) {
58	                    writableStates.<ProtoBytes>getSingleton(LEDGER_ID_STATE_ID).put(ProtoBytes.DEFAULT);
59	                }
60	                if (writableStates
61	                                .<HistoryProofConstruction>getSingleton(ACTIVE_PROOF_CONSTRUCTION_STATE_ID)
62	                                .get()
63	                        == null) {
64	                    writableStates
65	                            .<HistoryProofConstruction>getSingleton(ACTIVE_PROOF_CONSTRUCTION_STATE_ID)
66	                            .put(HistoryProofConstruction.DEFAULT);
67	                }
68	                if (writableStates
69	                                .<HistoryProofConstruction>getSingleton(NEXT_PROOF_CONSTRUCTION_STATE_ID)
70	                                .get()
71	                        == null) {
72	                    writableStates
73	                            .<HistoryProofConstruction>getSingleton(NEXT_PROOF_CONSTRUCTION_STATE_ID)
74	                            .put(HistoryProofConstruction.DEFAULT);
75	                }
76	                final var activeConstruction = writableStates
77	                        .<HistoryProofConstruction>getSingleton(ACTIVE_PROOF_CONSTRUCTION_STATE_ID)
78	                        .get();
79	                if (activeConstruction != null && activeConstruction.hasTargetProof()) {
80	                    historyService.setLatestHistoryProof(activeConstruction.targetProofOrThrow());
81	                }
82	            }
83	            final var hashState = ctx.newStates().<ProtoBytes>getSingleton(WRAPS_PROVING_KEY_HASH_STATE_ID);
84	            final var currentProtoBytes = hashState.get();
85	            if (currentProtoBytes == null) {
86	                hashState.put(ProtoBytes.DEFAULT);
87	            }
88	
89	            // Only put() when the configured hash actually differs from state. A no-op put of the
90	            // same value is captured by the boundary state-change listener as a spurious change,
91	            // which diverges numPrecedingStateChangesItems on replay -> SELF_ISS.
92	            final var configuredHash =
93	                    ctx.appConfig().getConfigData(TssConfig.class).wrapsProvingKeyHash();
94	            if (!isBlank(configuredHash)) {
95	                final var newHash = Bytes.fromHex(configuredHash);
