253	    @NonNull
254	    @Override
255	    public Outcome advance(
256	            @NonNull final Instant now,
257	            @NonNull final HistoryProofConstruction construction,
258	            @NonNull final Bytes targetMetadata,
259	            @NonNull final Map<Long, Bytes> targetProofKeys,
260	            @NonNull final TssConfig tssConfig,
261	            @Nullable final Bytes ledgerId,
262	            final boolean canSubmit) {
263	        requireNonNull(now);
264	        requireNonNull(construction);
265	        requireNonNull(targetMetadata);
266	        requireNonNull(targetProofKeys);
267	        requireNonNull(tssConfig);
268	        if (ledgerId == null && sourceProof != null) {
269	            return new Outcome.Failed("Only genesis WRAPS proofs are allowed to not have a ledger id");
270	        }
271	        final var state = construction.wrapsSigningStateOrElse(WrapsSigningState.DEFAULT);
272	        if (state.phase() != AGGREGATE
273	                && state.hasGracePeriodEndTime()
274	                && now.isAfter(asInstant(state.gracePeriodEndTimeOrThrow()))) {
275	            final var submittingNodes =
276	                    phaseMessages.getOrDefault(state.phase(), emptySortedMap()).keySet();
277	            // If we reached a stage with a grace period, we must have at least one R1 message, so no getOrDefault()
278	            final var missingNodes = phaseMessages.get(R1).keySet().stream()
279	                    .filter(nodeId -> !submittingNodes.contains(nodeId))
280	                    .toList();
281	            return new Outcome.Failed(MISSING_MESSAGES_FAILURE_PREFIX + missingNodes
282	                    + " after end of grace period for phase " + state.phase());
283	        } else {
284	            if (!canSubmit) {
285	                return Outcome.InProgress.INSTANCE;
286	            }
287	            if (wrapsMessage == null) {
288	                // Avoid caching a partial derived state if one of these computations throws.
289	                final var computedTargetAddressBook =
290	                        AddressBook.from(weights.targetNodeWeights(), nodeId -> targetProofKeys
291	                                .getOrDefault(nodeId, MISSING_SCHNORR_KEY)
292	                                .toByteArray());
293	                final var computedWrapsMessage =
294	                        historyLibrary.computeWrapsMessage(computedTargetAddressBook, targetMetadata.toByteArray());
295	                final var computedTargetAddressBookHash = historyLibrary.hashAddressBook(computedTargetAddressBook);
296	                targetAddressBook = computedTargetAddressBook;
297	                wrapsMessage = computedWrapsMessage;
298	                targetAddressBookHash = computedTargetAddressBookHash;
299	            }
300	            final var effectivePhase = construction.hasTargetProof() ? POST_AGGREGATION : state.phase();
301	            publishIfNeeded(
302	                    construction.constructionId(),
303	                    effectivePhase,
304	                    targetMetadata,
305	                    targetProofKeys,
306	                    tssConfig,
307	                    ledgerId,
308	                    construction.targetProof());
309	        }
310	        return Outcome.InProgress.INSTANCE;
311	    }
