333	    @Override
334	    public void observeProofVote(
335	            final long nodeId,
336	            @NonNull final HistoryProofVote vote,
337	            final boolean proofFinalized,
338	            @NonNull final ProofVoteCategory proofVoteCategory) {
339	        requireNonNull(vote);
340	        requireNonNull(proofVoteCategory);
341	        if (proofFinalized) {
342	            log.info("Observed finalized proof via node{}; skipping vote", nodeId);
343	            final var proofKind = proofKindOf(proofVoteCategory);
344	            final CompletableFuture<VoteDecision> decisionFuture;
345	            synchronized (voteLock) {
346	                markFinalized(proofKind);
347	                decisionFuture = voteFutureKind == null || voteFutureKind == proofKind ? voteDecisionFuture : null;
348	                if (decisionFuture != null) {
349	                    voteDecisionFuture = null;
350	                }
351	                if (voteFutureKind == proofKind) {
352	                    voteFuture = null;
353	                    voteFutureKind = null;
354	                }
355	            }
356	            if (decisionFuture != null) {
357	                decisionFuture.complete(VoteDecision.skip());
358	            }
359	            return;
360	        }
361	        // Explicit vote case
362	        if (vote.hasProof()) {
363	            final var proof = vote.proofOrElse(HistoryProof.DEFAULT);
364	            switch (proofVoteCategory) {
365	                case NOT_RECURSIVE -> {
366	                    // Always store a hash – useful if we haven't finished our own proof yet
367	                    final var hash = hashOf(proof);
368	                    final CompletableFuture<VoteDecision> decisionFuture;
369	                    synchronized (voteLock) {
370	                        explicitHistoryProofHashes.put(nodeId, hash);
371	                        // If we already have our proof, see if it matches; save a few bytes by using congruent vote
372	                        decisionFuture = (voteFutureKind == null || voteFutureKind == ProofKind.NON_RECURSIVE)
373	                                        && historyProof != null
374	                                        && selfProofHashOrThrow().equals(hash)
375	                                ? voteDecisionFuture
376	                                : null;
377	                    }
378	                    if (decisionFuture != null && decisionFuture.complete(VoteDecision.congruent(nodeId))) {
379	                        log.info("Observed matching explicit proof from node{}; voting congruent instead", nodeId);
380	                    }
381	                }
382	                case VALID_RECURSIVE -> {
383	                    // This is the big win, avoiding an explicit vote for the megabyte-scale WRAPS proof
384	                    final CompletableFuture<VoteDecision> decisionFuture;
385	                    synchronized (voteLock) {
386	                        validRecursiveProofNodeId = nodeId;
387	                        decisionFuture = voteFutureKind == null || voteFutureKind == ProofKind.RECURSIVE
388	                                ? voteDecisionFuture
389	                                : null;
390	                    }
391	                    if (decisionFuture != null && decisionFuture.complete(VoteDecision.congruent(nodeId))) {
392	                        log.info(
393	                                "Observed valid explicit recursive proof from node{}; voting congruent instead",
394	                                nodeId);
395	                    }
396	                }
397	                case INVALID_RECURSIVE -> {
398	                    // No-op, an invalid proof obviously has no use for us
399	                }
400	            }
401	        }
402	    }
