404	    @Override
405	    public boolean cancelPendingWork() {
406	        constructionCanceled = true;
407	        final var sb = new StringBuilder("Canceled work on WRAPS prover");
408	        boolean canceledSomething = false;
409	        if (r1Future != null && !r1Future.isDone()) {
410	            sb.append("\n  * In-flight R1 future");
411	            r1Future.cancel(true);
412	            canceledSomething = true;
413	        }
414	        if (r2Future != null && !r2Future.isDone()) {
415	            sb.append("\n  * In-flight R2 future");
416	            r2Future.cancel(true);
417	            canceledSomething = true;
418	        }
419	        if (r3Future != null && !r3Future.isDone()) {
420	            sb.append("\n  * In-flight R3 future");
421	            r3Future.cancel(true);
422	            canceledSomething = true;
423	        }
424	        if (voteFuture != null && !voteFuture.isDone()) {
425	            sb.append("\n  * In-flight vote future");
426	            voteFuture.cancel(true);
427	            canceledSomething = true;
428	        }
429	        if (canceledSomething) {
430	            log.info(sb.toString());
431	        }
432	        return canceledSomething;
433	    }
