435	    private boolean receiveWrapsSigningMessage(
436	            final long constructionId,
437	            @NonNull final WrapsMessagePublication publication,
438	            @Nullable final WritableHistoryStore writableHistoryStore) {
439	        if (MISSING_SCHNORR_KEY.equals(proofKeys.getOrDefault(publication.nodeId(), MISSING_SCHNORR_KEY))) {
440	            // If a node did not publish its Schnorr key in time to make it into the source roster,
441	            // we ignore any WRAPS message it publishes later after coming online
442	            return false;
443	        }
444	        final var transition = machine.onNext(publication, wrapsPhase, weights, wrapsMessageGracePeriod, phaseMessages);
445	        log.info(
446	                "Received {} message from node{} for construction #{} in phase={}) -> {} (new phase={})",
447	                publication.phase(),
448	                publication.nodeId(),
449	                constructionId,
450	                wrapsPhase,
451	                transition.publicationAccepted() ? "accepted" : "rejected",
452	                transition.newCurrentPhase());
453	        if (transition.publicationAccepted()) {
454	            if (transition.newCurrentPhase() != wrapsPhase) {
455	                wrapsPhase = transition.newCurrentPhase();
456	                log.info("Advanced to {} for construction #{}", wrapsPhase, constructionId);
457	                if (writableHistoryStore != null) {
458	                    writableHistoryStore.advanceWrapsSigningPhase(
459	                            constructionId, wrapsPhase, transition.gracePeriodEndTimeUpdate());
460	                }
461	            }
462	            return true;
463	        }
464	        return false;
465	    }
466	
467	    /**
468	     * Ensures this node has published its WRAPS message or aggregate signature vote.
469	     */
470	    private void publishIfNeeded(
471	            final long constructionId,
472	            @NonNull final WrapsPhase phase,
473	            @NonNull final Bytes targetMetadata,
474	            @NonNull final Map<Long, Bytes> targetProofKeys,
475	            @NonNull final TssConfig tssConfig,
476	            @Nullable final Bytes ledgerId,
477	            @Nullable final HistoryProof aggregatedSignatureProof) {
478	        if (shouldSkipAfterCancellation(constructionId, phase)) {
479	            return;
480	        }
481	        final boolean isWrapsReadinessRetry = phase == phaseNeedingWrapsReadinessRetry;
482	        if (isWrapsReadinessRetry) {
483	            consumerOf(phase).accept(null);
484	            phaseNeedingWrapsReadinessRetry = null;
485	        }
486	        // Skip building sourceBook/proofKeyList/chained futures while the WRAPS library is still loading.
487	        final boolean needsWrapsForOutput =
488	                phase == POST_AGGREGATION || (phase == AGGREGATE && sourceProof != null && tssConfig.wrapsEnabled());
489	        // The genesis proof also needs the ledger id, which is not established at the instant the library
490	        // becomes ready; without this the phase proceeds and dereferences a null ledgerId.
491	        final String notReadyReason;
492	        if (!needsWrapsForOutput) {
493	            notReadyReason = null;
494	        } else if (!historyLibrary.wrapsProverReady(tssConfig.wrapsProvingKeyHash())) {
495	            notReadyReason = "WRAPS library is not ready";
496	        } else if (phase == POST_AGGREGATION && ledgerId == null) {
497	            notReadyReason = "ledger id is not yet available";
498	        } else {
499	            notReadyReason = null;
500	        }
501	        if (notReadyReason != null) {
502	            if (isWrapsReadinessRetry) {
503	                log.debug("Deferring {} output for construction #{}: {}", phase, constructionId, notReadyReason);
504	            } else {
505	                log.info(
506	                        "Deferring {} output for construction #{}: {} (will retry each consensus round until ready)",
507	                        phase,
508	                        constructionId,
509	                        notReadyReason);
510	            }
511	            phaseNeedingWrapsReadinessRetry = phase;
512	            return;
513	        }
514	        if (futureOf(phase) == null
515	                && (POST_MPC_PHASES.contains(phase)
516	                        || !phaseMessages.getOrDefault(phase, emptySortedMap()).containsKey(selfId))) {
517	            if (isWrapsReadinessRetry) {
518	                log.debug(
519	                        "Re-attempting publication of {} output on construction #{} after a WRAPS-not-ready noop",
520	                        phase,
521	                        constructionId);
522	            } else if (phase == POST_AGGREGATION) {
523	                log.info("Considering publication of vote for genesis WRAPS proof on construction #{}", constructionId);
524	            } else {
525	                log.info("Considering publication of WRAPS {} output on construction #{}", phase, constructionId);
526	            }
527	            final var sourceBook = AddressBook.from(weights.sourceNodeWeights(), nodeId -> proofKeys
528	                    .getOrDefault(nodeId, MISSING_SCHNORR_KEY)
529	                    .toByteArray());
530	            final var targetBook = requireNonNull(targetAddressBook);
531	            final var targetBookHash = requireNonNull(targetAddressBookHash);
532	            final var proofKeyList = proofKeyListFrom(targetProofKeys);
533	            consumerOf(phase)
534	                    .accept(outputFuture(
535	                                    phase,
536	                                    tssConfig,
537	                                    ledgerId,
538	                                    sourceBook,
539	                                    targetBook,
540	                                    targetMetadata,
541	                                    aggregatedSignatureProof)
542	                            .thenAcceptAsync(
543	                                    output -> {
544	                                        if (output == null) {
545	                                            if (phase == R1 || POST_MPC_PHASES.contains(phase)) {
546	                                                log.warn("Got null output for {} phase, skipping publication", phase);
547	                                            }
548	                                            return;
549	                                        }
550	                                        if (shouldSkipAfterCancellation(constructionId, phase)) {
551	                                            return;
552	                                        }
553	                                        switch (output) {
554	                                            case MessagePhaseOutput messageOutput -> {
555	                                                if (shouldSkipAfterCancellation(constructionId, phase)) {
556	                                                    return;
557	                                                }
558	                                                final var wrapsMessage = Bytes.wrap(messageOutput.message());
559	                                                submissions
560	                                                        .submitWrapsSigningMessage(phase, wrapsMessage, constructionId)
561	                                                        .join();
562	                                            }
563	                                            case AggregatePhaseOutput aggregatePhaseOutput -> {
564	                                                // We are doing a non-recursive proof via an aggregate signature
565	                                                final var aggregatedNodeSignatures = new AggregatedNodeSignatures(
566	                                                        Bytes.wrap(aggregatePhaseOutput.signature()),
567	                                                        new ArrayList<>(phaseMessages
568	                                                                .get(R1)
569	                                                                .keySet()),
570	                                                        targetMetadata);
571	                                                final var proof = HistoryProof.newBuilder()
572	                                                        .targetProofKeys(proofKeyList)
573	                                                        .targetHistory(
574	                                                                new History(Bytes.wrap(targetBookHash), targetMetadata))
575	                                                        .chainOfTrustProof(ChainOfTrustProof.newBuilder()
576	                                                                .aggregatedNodeSignatures(aggregatedNodeSignatures))
577	                                                        .build();
578	                                                scheduleVoteWithJitter(constructionId, tssConfig, proof);
579	                                            }
580	                                            case ProofPhaseOutput proofOutput -> {
581	                                                // We have a WRAPS proof
582	                                                final var recursiveProof = Bytes.wrap(proofOutput.compressed());
583	                                                final var uncompressedProof = Bytes.wrap(proofOutput.uncompressed());
584	                                                final var proof = HistoryProof.newBuilder()
585	                                                        .targetProofKeys(proofKeyList)
586	                                                        .targetHistory(
587	                                                                new History(Bytes.wrap(targetBookHash), targetMetadata))
588	                                                        .chainOfTrustProof(ChainOfTrustProof.newBuilder()
589	                                                                .wrapsProof(recursiveProof))
590	                                                        .uncompressedWrapsProof(uncompressedProof)
591	                                                        .build();
592	                                                scheduleVoteWithJitter(constructionId, tssConfig, proof);
593	                                            }
594	                                            case NoopOutput noopOutput -> {
595	                                                if (WRAPS_NOT_READY_FAILURE_PREFIX.equals(noopOutput.reason())
596	                                                        || LEDGER_ID_NOT_READY_FAILURE_PREFIX.equals(
597	                                                                noopOutput.reason())) {
598	                                                    // Flag instead of clearing voteFuture inline; the outer accept()
599	                                                    // hasn't returned yet.
600	                                                    log.debug(
601	                                                            "Deferring {} output: {} (will retry next round)",
602	                                                            phase,
603	                                                            noopOutput.reason());
604	                                                    phaseNeedingWrapsReadinessRetry = phase;
605	                                                } else {
606	                                                    log.info(
607	                                                            "Skipping publication of {} output: {}",
608	                                                            phase,
609	                                                            noopOutput.reason());
610	                                                }
611	                                            }
612	                                        }
613	                                    },
614	                                    executor)
615	                            .exceptionally(e -> {
616	                                log.error(
617	                                        "Failed to publish WRAPS {} message for construction #{}",
618	                                        phase,
619	                                        constructionId,
620	                                        e);
621	                                return null;
622	                            }));
623	        }
624	    }
625	
626	    private void scheduleVoteWithJitter(
627	            final long constructionId, @NonNull final TssConfig tssConfig, @NonNull final HistoryProof proof) {
628	        if (constructionCanceled) {
629	            log.info("Skipping vote scheduling on canceled construction #{}", constructionId);
630	            return;
631	        }
632	        final var proofKind = proofKindOf(proof);
633	        final var selfProofHash = hashOf(proof);
634	        final var decisionFuture = new CompletableFuture<VoteDecision>();
635	        final var submissionFuture = decisionFuture.thenCompose(decision -> switch (decision.choice()) {
636	            case SKIP -> CompletableFuture.completedFuture(null);
637	            case SUBMIT -> {
638	                final var congruentNodeId = decision.congruentNodeId();
639	                if (congruentNodeId != null) {
640	                    log.info(
641	                            "Submitting congruent vote to node{} for construction #{}",
642	                            congruentNodeId,
643	                            constructionId);
644	                    yield submissions.submitCongruentProofVote(constructionId, congruentNodeId);
645	                } else {
646	                    log.info("Submitting explicit proof vote for construction #{}", constructionId);
647	                    yield submissions.submitExplicitProofVote(constructionId, proof);
648	                }
649	            }
650	        });
651	        final VoteDecision immediateDecision;
652	        synchronized (voteLock) {
653	            if (constructionCanceled || isFinalized(proofKind)) {
654	                log.info(
655	                        "Skipping {} proof vote scheduling on finalized construction #{}",
656	                        proofKind == ProofKind.RECURSIVE ? "recursive" : "non-recursive",
657	                        constructionId);
658	                return;
659	            }
660	            this.historyProof = proof;
661	            immediateDecision = immediateDecisionFor(proofKind, selfProofHash);
662	            voteDecisionFuture = decisionFuture;
663	            voteFuture = submissionFuture;
664	            voteFutureKind = proofKind;
665	        }
666	        if (immediateDecision != null) {
667	            if (immediateDecision.congruentNodeId() != null) {
668	                log.info(
669	                        "Already observed usable explicit proof from node{}; voting congruent immediately",
670	                        immediateDecision.congruentNodeId());
671	            }
672	            decisionFuture.complete(immediateDecision);
673	            return;
674	        }
675	
676	        final long jitterMs = computeJitterMs(tssConfig, constructionId);
677	        final var delayed = delayer.delayedExecutor(jitterMs, MILLISECONDS, executor);
678	
679	        // If this is the first thread to complete the vote decision, we submit an explicit vote
680	        CompletableFuture.runAsync(() -> decisionFuture.complete(VoteDecision.explicit()), delayed);
681	    }
682	
683	    @Nullable
684	    private VoteDecision immediateDecisionFor(@NonNull final ProofKind proofKind, @NonNull final Bytes selfProofHash) {
685	        if (proofKind == ProofKind.RECURSIVE) {
686	            return validRecursiveProofNodeId == null ? null : VoteDecision.congruent(validRecursiveProofNodeId);
687	        }
688	        for (final var entry : explicitHistoryProofHashes.entrySet()) {
689	            if (selfProofHash.equals(entry.getValue())) {
690	                return VoteDecision.congruent(entry.getKey());
691	            }
692	        }
693	        return null;
694	    }
695	
696	    private boolean isFinalized(@NonNull final ProofKind proofKind) {
697	        return proofKind == ProofKind.RECURSIVE ? recursiveProofFinalized : nonRecursiveProofFinalized;
698	    }
699	
700	    private void markFinalized(@NonNull final ProofKind proofKind) {
701	        if (proofKind == ProofKind.RECURSIVE) {
702	            recursiveProofFinalized = true;
703	        } else {
704	            nonRecursiveProofFinalized = true;
705	        }
706	    }
707	
708	    private boolean shouldSkipAfterCancellation(final long constructionId, @NonNull final WrapsPhase phase) {
709	        if (constructionCanceled) {
710	            log.info("Skipping post-output work for WRAPS {} on canceled construction #{}", phase, constructionId);
711	            return true;
712	        }
713	        return false;
714	    }
715	
716	    private long computeJitterMs(@NonNull final TssConfig tssConfig, final long constructionId) {
717	        final var allNodes = new ArrayList<>(weights.targetNodeWeights().keySet());
718	        final int n = allNodes.size();
719	        final int selfIndex = allNodes.indexOf(selfId);
720	        final int leaderIndex = Math.floorMod((int) constructionId, n);
721	        final int rank = Math.floorMod(selfIndex - leaderIndex, n);
722	        return tssConfig.wrapsVoteJitterPerRank().toMillis() * rank;
723	    }
724	
725	    private CompletableFuture<WrapsPhaseOutput> outputFuture(
726	            @NonNull final WrapsPhase phase,
727	            @NonNull final TssConfig tssConfig,
728	            @Nullable final Bytes ledgerId,
729	            @NonNull final AddressBook sourceBook,
730	            @NonNull final AddressBook targetBook,
731	            @NonNull final Bytes targetMetadata,
732	            @Nullable final HistoryProof aggregatedSignatureProof) {
733	        final var message = requireNonNull(wrapsMessage);
734	        return CompletableFuture.supplyAsync(
735	                () -> switch (phase) {
736	                    case UNRECOGNIZED -> throw new IllegalArgumentException("Unrecognized phase");
737	                    case R1 -> {
738	                        if (entropy == null) {
739	                            entropy = new byte[32];
740	                            new SecureRandom().nextBytes(entropy);
741	                            yield new MessagePhaseOutput(historyLibrary.runWrapsPhaseR1(
742	                                    entropy,
743	                                    message,
744	                                    schnorrKeyPair.privateKey().toByteArray()));
745	                        }
746	                        yield null;
747	                    }
748	                    case R2 -> {
749	                        if (entropy != null && phaseMessages.get(R1).containsKey(selfId)) {
750	                            yield new MessagePhaseOutput(historyLibrary.runWrapsPhaseR2(
751	                                    entropy,
752	                                    message,
753	                                    rawMessagesFor(R1),
754	                                    schnorrKeyPair.privateKey().toByteArray(),
755	                                    sourceBook,
756	                                    phaseMessages.get(R1).keySet()));
757	                        }
758	                        yield null;
759	                    }
760	                    case R3 -> {
761	                        if (entropy != null && phaseMessages.get(R1).containsKey(selfId)) {
762	                            yield new MessagePhaseOutput(historyLibrary.runWrapsPhaseR3(
763	                                    entropy,
764	                                    message,
765	                                    rawMessagesFor(R1),
766	                                    rawMessagesFor(R2),
767	                                    schnorrKeyPair.privateKey().toByteArray(),
768	                                    sourceBook,
769	                                    phaseMessages.get(R1).keySet()));
770	                        }
771	                        yield null;
772	                    }
773	                    case AGGREGATE -> {
774	                        final var signers = phaseMessages.get(R1).keySet();
775	                        final var signature = historyLibrary.runAggregationPhase(
776	                                message,
777	                                rawMessagesFor(R1),
778	                                rawMessagesFor(R2),
779	                                rawMessagesFor(R3),
780	                                sourceBook,
781	                                signers);
782	                        if (signature == null) {
783	                            yield new NoopOutput("WRAPS aggregation returned null for nodes " + signers);
784	                        }
785	                        // Sans source proof, we are at genesis and need an aggregate signature proof right away
786	                        if (sourceProof == null || !tssConfig.wrapsEnabled()) {
787	                            final var isValid = historyLibrary.verifyAggregateSignature(
788	                                    message,
789	                                    sourceBook.nodeIds(),
790	                                    sourceBook.publicKeys(),
791	                                    sourceBook.weights(),
792	                                    signature);
793	                            if (!isValid) {
794	                                yield new NoopOutput("Invalid aggregate signature using nodes " + signers);
795	                            }
796	                            yield new AggregatePhaseOutput(
797	                                    signature, signers.stream().toList());
798	                        } else {
799	                            if (!historyLibrary.wrapsProverReady(tssConfig.wrapsProvingKeyHash())) {
800	                                yield new NoopOutput(WRAPS_NOT_READY_FAILURE_PREFIX);
801	                            }
802	                            final var isValid = historyLibrary.verifyAggregateSignature(
803	                                    message,
804	                                    sourceBook.nodeIds(),
805	                                    sourceBook.publicKeys(),
806	                                    sourceBook.weights(),
807	                                    signature);
808	                            if (!isValid) {
809	                                yield new NoopOutput("Invalid aggregate signature using nodes " + signers);
810	                            }
811	                            final long now = System.nanoTime();
812	                            log.info(
813	                                    """
814	                                            Constructing incremental WRAPS proof with:
815	                                              ledgerId={}
816	                                              sourceBook={}
817	                                              sourceProofHash={}
818	                                              targetMetadata={}
819	                                              aggregateSignature={}
820	                                              signers={}
821	                                              targetBook={}
822	                                            """,
823	                                    ledgerId,
824	                                    sourceBook,
825	                                    noThrowSha384HashOf(sourceProof.uncompressedWrapsProof()),
826	                                    targetMetadata,
827	                                    Bytes.wrap(signature),
828	                                    signers,
829	                                    targetBook);
830	                            final var proof = historyLibrary.constructIncrementalWrapsProof(
831	                                    requireNonNull(ledgerId).toByteArray(),
832	                                    sourceProof.uncompressedWrapsProof().toByteArray(),
833	                                    sourceBook,
834	                                    targetBook,
835	                                    targetMetadata.toByteArray(),
836	                                    signature,
837	                                    signers);
838	                            if (proof == null) {
839	                                yield new NoopOutput("Incremental WRAPS proof construction returned null");
840	                            }
841	                            final var output = new ProofPhaseOutput(proof.compressed(), proof.uncompressed());
842	                            logElapsed(
843	                                    constructionCanceled
844	                                            ? "constructing canceled incremental WRAPS proof"
845	                                            : "constructing incremental WRAPS proof -> " + output,
846	                                    now);
847	                            yield output;
848	                        }
849	                    }
850	                    case POST_AGGREGATION -> {
851	                        if (!historyLibrary.wrapsProverReady(tssConfig.wrapsProvingKeyHash())) {
852	                            yield new NoopOutput(WRAPS_NOT_READY_FAILURE_PREFIX);
853	                        }
854	                        if (ledgerId == null) {
855	                            yield new NoopOutput(LEDGER_ID_NOT_READY_FAILURE_PREFIX);
856	                        }
857	                        final var signature = requireNonNull(aggregatedSignatureProof)
858	                                .chainOfTrustProofOrThrow()
859	                                .aggregatedNodeSignaturesOrThrow()
860	                                .aggregatedSignature()
861	                                .toByteArray();
862	                        final var signers = new TreeSet<>(aggregatedSignatureProof
863	                                .chainOfTrustProofOrThrow()
864	                                .aggregatedNodeSignaturesOrThrow()
865	                                .signingNodeIds());
866	                        final long now = System.nanoTime();
867	                        log.info("""
868	                                        Constructing genesis WRAPS proof with:
869	                                          ledgerId={}
870	                                          targetMetadata={}
871	                                          aggregateSignature={}
872	                                          signers={}
873	                                          targetBook={}
874	                                        """, ledgerId, targetMetadata, Bytes.wrap(signature), signers, targetBook);
875	                        final var proof = historyLibrary.constructGenesisWrapsProof(
876	                                requireNonNull(ledgerId).toByteArray(),
877	                                targetMetadata.toByteArray(),
878	                                signature,
879	                                signers,
880	                                targetBook);
881	                        if (proof == null) {
882	                            yield new NoopOutput("Genesis WRAPS proof construction returned null");
883	                        }
884	                        final var output = new ProofPhaseOutput(proof.compressed(), proof.uncompressed());
885	                        logElapsed("constructing genesis WRAPS proof -> " + output, now);
886	                        yield output;
887	                    }
888	                },
889	                executor);
890	    }
891	
892	    private void logElapsed(@NonNull final String event, final long startNs) {
893	        final var duration = Duration.ofNanos(System.nanoTime() - startNs);
894	        log.info("FINISHED {} - took {}m {}s", event, duration.toMinutes(), duration.toSecondsPart());
895	    }
896	
897	    private byte[][] rawMessagesFor(@NonNull final WrapsPhase phase) {
898	        return phaseMessages.get(phase).values().stream()
899	                .map(WrapsMessagePublication::message)
900	                .map(Bytes::toByteArray)
901	                .toArray(byte[][]::new);
902	    }
903	
904	    private CompletableFuture<Void> futureOf(@NonNull final WrapsPhase phase) {
905	        return switch (phase) {
906	            case UNRECOGNIZED -> throw new IllegalArgumentException("Unrecognized phase");
907	            case R1 -> r1Future;
908	            case R2 -> r2Future;
909	            case R3 -> r3Future;
910	            case AGGREGATE, POST_AGGREGATION -> voteFuture;
911	        };
912	    }
913	
914	    private Consumer<CompletableFuture<Void>> consumerOf(@NonNull final WrapsPhase phase) {
915	        return switch (phase) {
916	            case UNRECOGNIZED -> throw new IllegalArgumentException("Unrecognized phase");
917	            case R1 -> f -> r1Future = f;
918	            case R2 -> f -> r2Future = f;
919	            case R3 -> f -> r3Future = f;
920	            case AGGREGATE -> f -> setVoteFuture(f, ProofKind.NON_RECURSIVE);
921	            case POST_AGGREGATION -> f -> setVoteFuture(f, ProofKind.RECURSIVE);
922	        };
923	    }
924	
925	    private void setVoteFuture(@Nullable final CompletableFuture<Void> future, @NonNull final ProofKind proofKind) {
926	        synchronized (voteLock) {
927	            voteFuture = future;
928	            voteFutureKind = future == null ? null : proofKind;
929	        }
930	    }
931	
932	    private Bytes selfProofHashOrThrow() {
933	        return explicitHistoryProofHashes.computeIfAbsent(selfId, k -> hashOf(requireNonNull(historyProof)));
934	    }
935	
936	    private static ProofKind proofKindOf(@NonNull final HistoryProof proof) {
937	        return proof.chainOfTrustProofOrElse(ChainOfTrustProof.DEFAULT).hasWrapsProof()
938	                ? ProofKind.RECURSIVE
939	                : ProofKind.NON_RECURSIVE;
940	    }
941	
942	    private static ProofKind proofKindOf(@NonNull final ProofVoteCategory category) {
943	        return category == ProofVoteCategory.NOT_RECURSIVE ? ProofKind.NON_RECURSIVE : ProofKind.RECURSIVE;
944	    }
945	
946	    private static Bytes hashOf(@NonNull final HistoryProof proof) {
947	        return noThrowSha384HashOf(HistoryProof.PROTOBUF.toBytes(proof));
948	    }
949	}
