328	            final var length = nonNull ? Integer.toString(publicKey.length) : "null";
329	            final boolean expectedLength = nonNull && publicKey.length == SCHNORR_PUBLIC_KEY_LENGTH;
330	            allNonNull &= nonNull;
331	            allExpectedLength &= expectedLength;
332	            details.add("#"
333	                    + i
334	                    + "(nonNull="
335	                    + nonNull
336	                    + ", length="
337	                    + length
338	                    + ", length=="
339	                    + SCHNORR_PUBLIC_KEY_LENGTH
340	                    + "="
341	                    + expectedLength
342	                    + ")");
343	        }
