345	        return new ValidationResult(
346	                valid,
347	                "allPublicKeysNonNull="
348	                        + allNonNull
349	                        + ", allPublicKeysLength=="
350	                        + SCHNORR_PUBLIC_KEY_LENGTH
351	                        + "="
352	                        + allExpectedLength
353	                        + ", publicKeyDetails="
354	                        + details);
355	    }
356	
357	    private record ValidationResult(boolean valid, @NonNull String details) {}
358	}
