2	package org.hiero.consensus.reconnect.impl;
3	
4	import static com.swirlds.logging.legacy.LogMarker.EXCEPTION;
5	import static org.hiero.consensus.platformstate.PlatformStateUtils.consensusTimestampOf;
6	import static org.hiero.consensus.platformstate.PlatformStateUtils.getInfoString;
7	import static org.hiero.consensus.platformstate.PlatformStateUtils.roundOf;
8	
9	import com.hedera.hapi.node.state.roster.Roster;
10	import com.swirlds.state.State;
11	import org.apache.logging.log4j.LogManager;
12	import org.apache.logging.log4j.Logger;
13	import org.hiero.consensus.state.signed.SignedState;
14	import org.hiero.consensus.state.signed.SignedStateInvalidException;
15	
16	/**
17	 * Validates a signed state by summing the amount of weight held by the valid signatures on the state.
18	 */
19	public class DefaultSignedStateValidator implements SignedStateValidator {
20	    private static final Logger logger = LogManager.getLogger(DefaultSignedStateValidator.class);
21	
22	    /**
23	     * {@inheritDoc}
24	     */
25	    public void validate(
26	            final SignedState signedState, final Roster roster, SignedStateValidationData previousStateData) {
27	        throwIfOld(signedState, previousStateData);
28	        signedState.pruneInvalidSignatures(roster);
29	        signedState.throwIfNotVerifiable();
30	    }
31	
32	    /**
33	     * Check the signed state against metadata from a prior state, and throw if the new state is older. After a
34	     * reconnect, there is a slight possibility the teacher sent older state than we already had.  In that case we do
35	     * not want to keep the state, but try again with a different teacher.  This method checks that the received state
36	     * is at least as new as the state we started with, and throws if the received state is not acceptable.
37	     *
38	     * @param signedState       a newly received signed state from a reconnect process.
39	     * @param previousStateData The validation data from the current address book and prior state, before reconnect.
40	     * @throws SignedStateInvalidException if the signed state is not at least as new as the previous state.
41	     */
42	    private void throwIfOld(final SignedState signedState, final SignedStateValidationData previousStateData)
43	            throws SignedStateInvalidException {
44	
45	        State state = signedState.getState();
46	        if (roundOf(state) < previousStateData.round()
47	                || consensusTimestampOf(state).isBefore(previousStateData.consensusTimestamp())) {
48	            logger.error(EXCEPTION.getMarker(), """
49	                            State is too old. Failed reconnect state:
50	                            {}
51	                            Original reconnect state:
52	                            {}""", getInfoString(state), previousStateData.getInfoString());
53	            throw new SignedStateInvalidException(("Received signed state is for a round smaller than or a "
54	                            + "consensus earlier than what we started with. Original round %d, received round %d. "
55	                            + "Original timestamp %s, received timestamp %s.")
56	                    .formatted(
57	                            previousStateData.round(),
58	                            signedState.getRound(),
59	                            previousStateData.consensusTimestamp(),
60	                            signedState.getConsensusTimestamp()));
61	        }
62	    }
63	}
