420	export function inspectTrustClosure(input: InspectTrustClosureInput): InspectTrustClosureResult {
421		try {
422			const record = snapshotClosedRecord(input, ["candidates", "closure"]);
423			if (record === undefined) return failure("malformed-input");
424			const closure = copyClosure(record.closure);
425			if (closure === undefined) return failure("closure-invalid");
426			const candidates = copyCandidates(record.candidates);
427			if (candidates === undefined) return failure("candidate-invalid");
428			return inspectCopiedClosure(closure, candidates);
429		} catch {
430			return failure("malformed-input");
431		}
432	}
433	
434	/**
435	 * Establishes that a previously selected trust reference survives a proposed detached closure.
436	 * @param input - Proposed closure data and the previously selected trust reference.
437	 * @returns The preserved trust-state bytes and reference, or the first closed rejection.
438	 */
439	export function assertTrustPreserved(input: AssertTrustPreservedInput): AssertTrustPreservedResult {
440		try {
441			const record = snapshotClosedRecord(input, ["candidates", "closure", "expectedTrustRef"]);
442			if (record === undefined) return failure("malformed-input");
443			const expectedTrustRef = copyRef(record.expectedTrustRef);
444			if (expectedTrustRef === undefined) return failure("malformed-input");
445			const inspected = inspectTrustClosure({ candidates: record.candidates as never, closure: record.closure as never });
446			if (!inspected.ok) return inspected;
447			if (!sameRef(inspected.trustRef, expectedTrustRef)) return failure("trust-ref-not-preserved");
448			return inspected;
449		} catch {
450			return failure("malformed-input");
451		}
452	}
453	
454	function sameBytes(left: Uint8Array, right: Uint8Array): boolean {
455		if (left.byteLength !== right.byteLength) return false;
456		for (let index = 0; index < left.byteLength; index += 1) {
457			if (left[index] !== right[index]) return false;
458		}
459		return true;
460	}
461	
462	function sameHead(left: PresentHead, right: PresentHead): boolean {
463		return (
464			left.closureDigest === right.closureDigest &&
465			left.generationId === right.generationId &&
466			left.objectId === right.objectId &&
467			left.revision === right.revision
468		);
469	}
470	
471	function snapshotActiveRecovery(
472		value: unknown,
473		expectedHead: PresentHead
474	): Readonly<{ head: PresentHead; references: readonly GenerationRef[] }> | undefined {
475		const result = snapshotStoreResult(value);
476		if (result === undefined || !result.ok) return undefined;
477		const active = snapshotClosedRecord(result.value, [
478			"adoptedGeneration",
479			"head",
480			"kind",
481			"recomputedClosureDigest",
482			"references",
483		]);
484		if (active === undefined || active.kind !== "active") return undefined;
485		const head = snapshotPresentHead(active.head);
486		const references = copyClosure(active.references);
487		if (
488			head === undefined ||
489			references === undefined ||
490			!sameHead(head, expectedHead) ||
491			active.recomputedClosureDigest !== head.closureDigest
492		)
493			return undefined;
494		const adopted = snapshotGenerationRecord(active.adoptedGeneration, {
495			closure: references,
496			generationId: head.generationId,
497			objectId: head.objectId,
498			state: "Adopted",
499		});
500		if (adopted === undefined || adopted.closureDigest !== head.closureDigest) return undefined;
501		return Object.freeze({ head, references });
502	}
503	
504	function snapshotLoadedBlob(value: unknown): Uint8Array | undefined {
505		const result = snapshotStoreResult(value);
506		return result?.ok === true ? copyDetachedBytes(result.value) : undefined;
507	}
508	
509	function successfulOpen(value: OpenedStoredTrust): OpenDurableCurrentAnchorTrustResult {
510		return Object.freeze({
511			head: Object.freeze({ ...value.head }),
512			ok: true as const,
513			trust: value.trust,
514			trustRef: Object.freeze({ ...value.trustRef }),
515		});
516	}
517	
518	function freshGenerationId(): GenerationId | undefined {
519		try {
520			const bytes = new Uint8Array(32);
521			globalThis.crypto.getRandomValues(bytes);
522			const text = Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("");
523			const parsed = parseGenerationId(text);
524			return parsed.ok ? parsed.value : undefined;
525		} catch {
526			return undefined;
527		}
528	}
529	
530	/**
531	 * Creates the sole durable owner for creator current-anchor trust.
532	 * @param options - Fixed storage owner, genesis pin, and strict durable AHE store.
533	 * @returns The immutable install/open authority for the fixed object.
534	 */
535	export function createCurrentAnchorTrustStore(options: CurrentAnchorTrustStoreOptions): CurrentAnchorTrustStore {
536		const objectId = options.objectId;
537		const pinnedGenesisAnchorDigest = options.pinnedGenesisAnchorDigest;
538		const store = options.store;
539	
540		const openAtHead = async (expectedHead: PresentHead): Promise<OpenedStoredTrustResult> => {
541			try {
542				const recovered = snapshotActiveRecovery(await store.recoverActiveGeneration(objectId), expectedHead);
543				if (recovered === undefined) return failure("trust-state-unreadable");
544				const candidates: DetachedClosureCandidate[] = [];
545				for (let index = 0; index < recovered.references.length; index += 1) {
546					const ref = recovered.references[index] as GenerationRef;
547					if (ref.byteLength > MAX_SCANNABLE_BYTES) continue;
548					const bytes = snapshotLoadedBlob(await store.getBlob(ref.digest));
549					if (bytes === undefined) return failure("trust-state-unreadable");
550					candidates.push(Object.freeze({ bytes, ref }));
551				}
552				const inspected = inspectTrustClosure({ candidates, closure: recovered.references });
553				if (!inspected.ok) return causedFailure("closure-rejected", inspected.reason);
554				const opened = openCurrentAnchorTrust({
555					exactCanonicalTrustStateRecordBytes: inspected.exactCanonicalTrustStateRecordBytes,
556					expectedObjectId: objectId,
557					pinnedGenesisAnchorDigest,
558				});
559				if (!opened.ok) return causedFailure("trust-rejected", opened.reason);
560				return Object.freeze({
561					ok: true as const,
562					value: Object.freeze({
563						bytes: inspected.exactCanonicalTrustStateRecordBytes,
564						head: recovered.head,
565						trust: opened.trust,
566						trustRef: inspected.trustRef,
567					}),
568				});
569			} catch {
570				return failure("trust-state-unreadable");
571			}
572		};
573	
574		const open = async (): Promise<OpenDurableCurrentAnchorTrustResult> => {
575			if (!snapshotStrictDurability(store)) return failure("store-failed");
576			try {
577				const read = snapshotStoreResult(await store.readHead(objectId));
578				if (read === undefined || !read.ok) return failure("store-failed");
579				const head = snapshotExpectedHead(read.value, objectId);
580				if (head === undefined) return failure("store-failed");
581				if (head.kind === "none") return failure("not-installed");
582				const opened = await openAtHead(head);
583				return opened.ok ? successfulOpen(opened.value) : opened;
584			} catch {
585				return failure("store-failed");
586			}
587		};
588	
589		const install = async (input: InstallCreatorAnchorTrustRootInput): Promise<InstallCurrentAnchorTrustResult> => {
590			const installed = installCreatorAnchorTrustRoot(input);
591			if (!installed.ok) return causedFailure("genesis-rejected", installed.reason);
592			const openedFresh = openCurrentAnchorTrust({
593				exactCanonicalTrustStateRecordBytes: installed.exactCanonicalTrustStateRecordBytes,
594				expectedObjectId: objectId,
595				pinnedGenesisAnchorDigest,
596			});
597			if (!openedFresh.ok) return causedFailure("trust-rejected", openedFresh.reason);
598			const exactBytes = new Uint8Array(installed.exactCanonicalTrustStateRecordBytes);
599			const digest = digestBlob(exactBytes);
600			if (!digest.ok) return failure("store-failed");
601			const trustRef = Object.freeze({ byteLength: exactBytes.byteLength, digest: digest.value });
602			const inspected = inspectTrustClosure({ candidates: [{ bytes: exactBytes, ref: trustRef }], closure: [trustRef] });
603			if (!inspected.ok) return causedFailure("closure-rejected", inspected.reason);
604			if (!snapshotStrictDurability(store)) return failure("store-failed");
605	
606			try {
607				const read = snapshotStoreResult(await store.readHead(objectId));
608				if (read === undefined || !read.ok) return failure("store-failed");
609				const head = snapshotExpectedHead(read.value, objectId);
610				if (head === undefined) return failure("store-failed");
611				if (head.kind === "present") {
612					const existing = await openAtHead(head);
613					if (!existing.ok) return existing.reason === "trust-state-unreadable" ? failure("store-failed") : existing;
614					return sameBytes(existing.value.bytes, exactBytes)
615						? failure("already-installed")
616						: failure("trust-state-conflict");
617				}
618			} catch {
619				return failure("store-failed");
620			}
621	
622			const generationId = freshGenerationId();
623			if (generationId === undefined) return failure("store-failed");
624			const baseExpectedHead: ExpectedHead = Object.freeze({ kind: "none", objectId });
625			try {
626				const begun = snapshotStoreResult(
627					await store.beginGeneration({
628						baseExpectedHead,
629						closure: [trustRef],
630						generationId,
631						objectId,
632					})
633				);
634				const begunRecord =
635					begun?.ok === true
636						? snapshotGenerationRecord(begun.value, {
637								baseExpectedHead,
638								closure: [trustRef],
639								generationId,
640								objectId,
641								state: "Staged",
642							})
643						: undefined;
644				if (begunRecord === undefined) return failure("store-failed");
645				const cached = snapshotStoreResult(
646					await store.putCachedBlob({ bytes: exactBytes, digest: trustRef.digest, generationId, objectId })
647				);
648				const cachedValue = cached?.ok === true ? snapshotClosedRecord(cached.value, ["inserted"]) : undefined;
649				if (cachedValue === undefined || typeof cachedValue.inserted !== "boolean") return failure("store-failed");
650				const promoted = snapshotStoreResult(
651					await store.promoteReference({ digest: trustRef.digest, generationId, objectId })
652				);
653				if (promoted?.ok !== true || promoted.value !== undefined) return failure("store-failed");
654				const completed = snapshotStoreResult(await store.completeGeneration({ generationId, objectId }));
655				const completedRecord =
656					completed?.ok === true
657						? snapshotGenerationRecord(completed.value, {
658								baseExpectedHead,
659								closure: [trustRef],
660								generationId,
661								objectId,
662								state: "Complete",
663							})
664						: undefined;
665				if (completedRecord === undefined || completedRecord.closureDigest !== begunRecord.closureDigest)
666					return failure("store-failed");
667				const swapped = snapshotStoreResult(
668					await store.swapHead({ expectedHead: baseExpectedHead, generationId, objectId })
669				);
670				if (swapped?.ok === true) {
671					const swapValue = snapshotClosedRecord(swapped.value, ["head", "supersededGenerationId"]);
672					const head = swapValue === undefined ? undefined : snapshotPresentHead(swapValue.head);
673					if (
674						head === undefined ||
675						head.objectId !== objectId ||
676						head.generationId !== generationId ||
677						head.closureDigest !== completedRecord.closureDigest ||
678						head.revision !== 1 ||
679						swapValue?.supersededGenerationId !== null
680					)
681						return failure("store-failed");
682					return Object.freeze({
683						head,
684						ok: true as const,
685						trust: openedFresh.trust,
686						trustRef: Object.freeze({ ...trustRef }),
687					});
688				}
689				if (swapped?.reason !== "HEAD_CONFLICT") return failure("store-failed");
690			} catch {
691				return failure("store-failed");
692			}
693	
694			try {
695				const winnerRead = snapshotStoreResult(await store.readHead(objectId));
696				if (winnerRead === undefined || !winnerRead.ok) return failure("store-failed");
697				const winnerHead = snapshotExpectedHead(winnerRead.value, objectId);
698				if (winnerHead?.kind !== "present") return failure("store-failed");
699				const winner = await openAtHead(winnerHead);
700				if (!winner.ok) return winner.reason === "trust-state-unreadable" ? failure("store-failed") : winner;
701				return sameBytes(winner.value.bytes, exactBytes) ? failure("already-installed") : failure("trust-state-conflict");
702			} catch {
703				return failure("store-failed");
704			}
705		};
706	
707		return Object.freeze({ install, open });
708	}
